  const root = [null, null];
  let best = 0;

  for (const num of nums) {
    let node = root;
    for (let bit = highBit; bit >= 0; bit--) {
      const digit = (num >> bit) & 1;
      if (node[digit] === null) {
        node[digit] = [null, null];
      }
      node = node[digit];
    }

    let probe = root;
    let current = 0;
    for (let bit = highBit; bit >= 0; bit--) {
      const digit = (num >> bit) & 1;
      const want = 1 - digit;
      if (probe[want] !== null) {
        current |= 1 << bit;
        probe = probe[want];
      } else {
        probe = probe[digit];
      }
    }
    best = Math.max(best, current);
  }
  return best;
}

