      // Every number shares the same high bits, so only the low bits decide the answer.
      const base = Math.floor(rand() * 1024) * 2097152;
      return [Array.from({ length: n }, () => base + Math.floor(rand() * 2097152))];
    }
    return [Array.from({ length: n }, () => Math.floor(rand() * 1000))];
  }
  const n = 1 + Math.floor(rand() * 10);
  const pick = rand();
  const span = pick < 0.4 ? 16 : pick < 0.7 ? 1024 : full;
  return [Array.from({ length: n }, () => Math.floor(rand() * span))];
